        require(address(this).balance >= amount, "insufficient balance");

        uint preBank = c.bank().balance;
        address bankAddr = c.bank(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
